    pixelroot32::graphics::TileMap4bpp items;

    void init() {
        // Every interior owns the same one slot of the global
        // background bank; city_scene::init() binds the other
        // seven. Binding it twice is binding it to the same
        // sixteen colours, which is why the rooms can share it.
        pixelroot32::graphics::setBackgroundCustomPaletteSlot(4, INTERIOR_PALETTE);

        // BACKGROUND
        background.width = MAP_WIDTH;
        background.height = MAP_HEIGHT;
        background.tileWidth = TILE_SIZE;
        background.tileHeight = TILE_SIZE;
        background.indices = (uint8_t*)BACKGROUND_INDICES;
        background.tiles = BACKGROUND_TILESET_SPRITES;
        background.tileCount = 5;
        background.runtimeMask = nullptr;
        background.animManager = nullptr;
        background.paletteIndices = BACKGROUND_PALETTE_INDICES;

        // ITEMS
        items.width = MAP_WIDTH;
        items.height = MAP_HEIGHT;
        items.tileWidth = TILE_SIZE;
        items.tileHeight = TILE_SIZE;
        items.indices = (uint8_t*)ITEMS_INDICES;
        items.tiles = ITEMS_TILESET_SPRITES;
        items.tileCount = 9;
        items.runtimeMask = nullptr;
        items.animManager = nullptr;
        items.paletteIndices = ITEMS_PALETTE_INDICES;

    }

